import logging
import time
import random
import string

from ute_ue.config import loggers as ute_ue_logging
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ta_ue_plugin_ultracaller.exceptions import UltraCallerTestPhaseException, UltraCallerTestNotRunning, \
    UltraCallerTestReturnsError, UltraCallerTestStartFailed
from ..uc_connection import UcPhase, UcStatus


class UcDataTransferBase(LteDataTransfer):
    """Implementation of generic UltraCaller test"""

    def __init__(self, name, dt_definition, configuration, uc_connection, logger_name='ute_ue', test_name=None):
        """
        Initialization of UltraCaller test

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param uc_connection:
        :param logger_name:
        :param test_name:
        """
        super(UcDataTransferBase, self).__init__(name, dt_definition, configuration, logger_name)
        if test_name:
            self.test_name = test_name
            self.existing_uc_test = True
        else:
            self.test_name = '{}_{}'.format(self.name, ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(5)))
            self.existing_uc_test = False
        self._uc_connection = uc_connection
        self._imei = configuration['imei']
        self._test_id = None
        self._running = False

        raw_logger = logging.getLogger(logger_name)
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'ULTRACALLERTEST'})

    def start(self):
        """
        Start data transfer
        :return:
        """
        raise NotImplementedError()

    def _start_and_wait_for_running(self):
        """
        Start UltraCaller test
        :return:
        :raises: UltraCallerTestPhaseException if not started within timeout
        """
        self.logger.info('Starting UltraCaller test "{}"'.format(self.test_name))

        response = self._uc_connection.start_test(imei=self._imei, test_name=self.test_name)
        self._test_id = response['data'][0]['testId']

        phase = self._wait_until_test_phase([UcPhase.RUNNING, UcPhase.COMPLETED])
        if phase == UcPhase.RUNNING:
            self._running = True
            self.logger.info('Started UltraCaller test "{}"'.format(self.test_name))
        elif phase == UcPhase.COMPLETED:
            self.logger.info('Started and finished UltraCaller test "{}"'.format(self.test_name))
        else:
            err_msg = 'UltraCaller Test "{}" FAILED to start within time limit'.format(self.test_name)
            self.logger.error(err_msg)
            raise UltraCallerTestStartFailed(err_msg)

    def _start_and_wait_for_complete(self):
        self.logger.info('Starting UltraCaller test "{}"'.format(self.test_name))

        response = self._uc_connection.start_test(imei=self._imei, test_name=self.test_name)
        self._test_id = response['data'][0]['testId']

        phase = self._wait_until_test_phase([UcPhase.COMPLETED])
        if phase == UcPhase.COMPLETED:
            self.logger.info('Started and finished UltraCaller test "{}"'.format(self.test_name))
        else:
            err_msg = 'UltraCaller Test "{}" FAILED to start within time limit'.format(self.test_name)
            self.logger.error(err_msg)
            raise UltraCallerTestStartFailed(err_msg)

    def stop(self):
        """
        Stop UltraCaller test
        :return:
        :raises: UltraCallerTestPhaseException if not stopped within timeout
        """
        self.logger.info('Stopping UltraCaller test "{}"'.format(self.test_name))
        self._stop_and_wait_for_completed()

    def _stop_and_wait_for_completed(self):
        self._uc_connection.stop_test(imei=self._imei, test_id=self._test_id)
        phase = self._uc_connection.wait_until_test_phase(test_id=self._test_id, phase=UcPhase.COMPLETED)
        if not self.existing_uc_test:
            self._delete_test()
        if phase == UcPhase.COMPLETED:
            self._running = False
        else:
            self.logger.error('UltraCaller test "{}" FAILED to stop within time limit'.format(self.test_name))
            raise UltraCallerTestPhaseException('completed')

    def _delete_test(self):
        self._uc_connection.delete_test(test_name=self.test_name)

    def get_status(self):
        """
        Get status of UltraCaller test
        :return: List of dictionaries
        """
        response = self._uc_connection.test_status(test_id=self._test_id)
        return response['data']

    def get_results(self):
        """
        Get results of UltraCaller test
        :return: List of dictionaries
        """
        response = self._uc_connection.get_test_result(test_id=self._test_id)
        # TODO: We could sort here with timestamp since server gives data in random order
        # This would be easier for testers
        return response['data']

    def await_finish(self, timeout=0):
        """
        Waits until this uc test finishes.
        No action if given uc test is already finished.
        :param timeout: Timeout in seconds, 0=forever
        :raises: UltraCallerTestNotRunning if test is not running
        :raises: UltraCallerTestPhaseException if UC UE fails to finish within time limit
        :return: None
        """
        if not self._running:
            raise UltraCallerTestNotRunning(self.test_name)

        if int(timeout) == 0:
            timeout = 43200  # 12 hours

        phase = self._uc_connection.wait_until_test_phase(test_id=self._test_id, phase=UcPhase.COMPLETED, wait_time=int(timeout))
        if phase == UcPhase.COMPLETED:
            self._running = False
            if not self.existing_uc_test:
                self._delete_test()
        else:
            self.logger.error('UltraCaller test "{}" FAILED to stop within time limit'.format(self.test_name))
            self.stop()
            raise UltraCallerTestPhaseException('completed')

    def _wait_until_test_phase(self, phase, wait_time=40):
        phase_list = phase if isinstance(phase, list) else [phase]
        started_waiting = time.time()
        while time.time() < started_waiting + wait_time:
            time.sleep(5)
            response = self._uc_connection.test_status(self._test_id)
            if response['data']['phase'] in phase_list:
                if response['data']['status'] == UcStatus.ERROR:
                    raise UltraCallerTestReturnsError(response['data']['info'])
                break
        return response['data']['phase']
